      'varying vec3 vHouseP;\nattribute float aHouseAO;\n' +
      'uniform float uSag, uSagL, uSagY0, uSagY1;\n' +
      'float hSag(vec3 p) {\n' +
      '  float bx = max(0.0, 1.0 - (p.x * p.x) / max(uSagL * uSagL, 0.01));\n' +
      '  float ky = clamp((p.y - uSagY0) / max(uSagY1 - uSagY0, 0.01), 0.0, 1.0);\n' +
